CREATE OR REPLACE FUNCTION public.hr_assert_payment_destination_school()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_school uuid;
BEGIN
  SELECT school_id INTO v_school FROM public.hr_employments WHERE id = NEW.employment_id;
  IF v_school IS DISTINCT FROM NEW.school_id THEN
    RAISE EXCEPTION 'HR cross-school payment destination reference';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at_and_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.created_by = OLD.created_by;
  NEW.updated_by = COALESCE((SELECT auth.uid()), NEW.updated_by);
  NEW.updated_at = now();
  NEW.version = COALESCE(OLD.version, 0) + 1;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  row_before jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else '{}'::jsonb end;
  row_after jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else '{}'::jsonb end;
  source_row jsonb := case when tg_op = 'DELETE' then row_before else row_after end;
  target_school_id uuid;
  target_entity_id uuid;
  changed_fields jsonb := '[]'::jsonb;
begin
  if tg_table_name = 'schools' then
    target_school_id := (source_row->>'id')::uuid;
  else
    target_school_id := (source_row->>'school_id')::uuid;
  end if;

  if coalesce(source_row->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    target_entity_id := (source_row->>'id')::uuid;
  end if;

  if tg_op = 'UPDATE' then
    select coalesce(jsonb_agg(key order by key), '[]'::jsonb)
      into changed_fields
    from jsonb_each(row_after) item
    where (row_before -> item.key) is distinct from item.value;
  end if;

  insert into public.audit_logs (
    school_id,
    actor_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  ) values (
    target_school_id,
    (select auth.uid()),
    tg_table_name || '.' || lower(tg_op),
    tg_table_name,
    target_entity_id,
    jsonb_build_object('operation', lower(tg_op), 'changed_fields', changed_fields)
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_academic_calendar_manager_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_actor uuid;
  v_year_start date;
  v_year_end date;
BEGIN
  IF NOT private.sga_request_is_service_role() THEN
    RETURN NEW;
  END IF;

  v_actor := COALESCE(NEW.updated_by, NEW.created_by);
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Mutação do calendário académico sem actor autenticado.'
      USING ERRCODE = '42501';
  END IF;

  IF NOT private.sga_actor_is_academic_manager(v_actor, NEW.school_id) THEN
    RAISE EXCEPTION 'Apenas Administração/Secretaria pode alterar o calendário académico.'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.school_id IS DISTINCT FROM OLD.school_id THEN
    RAISE EXCEPTION 'Não é permitido mover o calendário entre escolas.'
      USING ERRCODE = '42501';
  END IF;

  IF TG_TABLE_NAME = 'academic_years' THEN
    IF NEW.starts_on IS NULL OR NEW.ends_on IS NULL OR NEW.starts_on > NEW.ends_on THEN
      RAISE EXCEPTION 'Ano lectivo com intervalo de datas inválido.' USING ERRCODE = '22007';
    END IF;
  ELSIF TG_TABLE_NAME = 'terms' THEN
    IF NEW.sequence NOT BETWEEN 1 AND 3 THEN
      RAISE EXCEPTION 'O SIGA exige trimestre 1, 2 ou 3.' USING ERRCODE = '22023';
    END IF;
    IF NEW.starts_on IS NULL OR NEW.ends_on IS NULL OR NEW.starts_on > NEW.ends_on THEN
      RAISE EXCEPTION 'Trimestre com intervalo de datas inválido.' USING ERRCODE = '22007';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.academic_year_id IS DISTINCT FROM OLD.academic_year_id THEN
      RAISE EXCEPTION 'Não é permitido mover um trimestre para outro ano lectivo.'
        USING ERRCODE = '42501';
    END IF;

    SELECT ay.starts_on, ay.ends_on
      INTO v_year_start, v_year_end
    FROM public.academic_years ay
    WHERE ay.id = NEW.academic_year_id
      AND ay.school_id = NEW.school_id;

    IF v_year_start IS NULL OR v_year_end IS NULL THEN
      RAISE EXCEPTION 'Ano lectivo da escola não encontrado para este trimestre.'
        USING ERRCODE = '23503';
    END IF;
    IF NEW.starts_on < v_year_start OR NEW.ends_on > v_year_end THEN
      RAISE EXCEPTION 'As datas do trimestre devem ficar dentro do ano lectivo.'
        USING ERRCODE = '22007';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_term_within_year()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE y record;
BEGIN
  IF NEW.starts_on IS NOT NULL AND NEW.ends_on IS NOT NULL AND NEW.starts_on >= NEW.ends_on THEN
    RAISE EXCEPTION 'O período tem de terminar depois de começar.' USING ERRCODE = '23514';
  END IF;
  SELECT starts_on, ends_on INTO y FROM academic_years WHERE id = NEW.academic_year_id;
  IF FOUND AND (NEW.starts_on < y.starts_on OR NEW.ends_on > y.ends_on) THEN
    RAISE EXCEPTION 'O período tem de ficar dentro das datas do ano lectivo.' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(current_setting('siga.defer_term_overlap', true), '') <> 'on'
     AND EXISTS (SELECT 1 FROM terms t WHERE t.id <> NEW.id AND t.academic_year_id = NEW.academic_year_id
             AND t.starts_on <= NEW.ends_on AND NEW.starts_on <= t.ends_on) THEN
    RAISE EXCEPTION 'O período sobrepõe-se a outro período do mesmo ano lectivo.' USING ERRCODE = '23P01';
  END IF;
  RETURN NEW;
END $function$
